.btn-submit {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  width: 100%;
  padding: 0.75rem 1.5rem;
  background: var(--accent);
  color: #0d1117;
  font-size: 0.9375rem;
  font-weight: 700;
  border: none;
