  position: absolute;
  top: -4rem;
  left: 1rem;
  padding: 0.5rem 1rem;
  background: var(--accent);
  color: var(--bg);
  font-weight: 700;
  border-radius: var(--radius);
  text-decoration: none;
  z-index: 100;
  transition: top 0.15s;
}
.skip-link:focus { top: 1rem; }

/* ── Card ─────────────────────────────────────────────────────── */
.card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: calc(var(--radius) * 1.5);
  box-shadow: var(--shadow);
  width: 100%;
  max-width: 30rem;
  padding: 2rem;
}

.card__eyebrow {
  font-size: 0.75rem;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--accent);
  margin-bottom: 0.375rem;
}

.card__title {
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--text);
  line-height: 1.25;
  margin-bottom: 0.5rem;
}

.card__subtitle {
  font-size: 0.9rem;
  color: var(--text-muted);
  margin-bottom: 1.75rem;
}

/* ── Required legend ──────────────────────────────────────────── */
.required-note {
  font-size: 0.8rem;
  color: var(--text-muted);
  margin-bottom: 1.25rem;
}
.required-note .star { color: var(--error); }

/* ── Form field ───────────────────────────────────────────────── */
.form-field {
  border: none;
  padding: 0;
  min-inline-size: 0;
}

.form-field legend {
  font-size: 0.9rem;
  font-weight: 600;
  color: var(--text);
  margin-bottom: 1rem;
  line-height: 1.4;
  float: left;
  width: 100%;
}
/* Clear float so options sit below the legend */
.form-field legend + * { clear: both; }

.form-field legend .star { color: var(--error); margin-left: 0.125rem; }

/* ── Radio options ────────────────────────────────────────────── */
.radio-options {
  display: flex;
  flex-direction: column;
  gap: 0.625rem;
}

.radio-label {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  padding: 0.75rem 1rem;
  background: var(--card);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  cursor: pointer;
  font-size: 0.9375rem;
  color: var(--text-muted);
  transition: border-color 0.15s, color 0.15s, background 0.15s;
  user-select: none;
}

.radio-label:hover {
  border-color: var(--accent);
  color: var(--text);
  background: color-mix(in srgb, var(--accent) 8%, var(--card));
}

/* Native radio hidden, custom circle shown */
.radio-input {
  appearance: none;
  -webkit-appearance: none;
  width: var(--radio-size);
  height: var(--radio-size);
  min-width: var(--radio-size);
  border: 2px solid var(--border);
  border-radius: 50%;
  background: var(--bg);
  cursor: pointer;
  position: relative;
  transition: border-color 0.15s, background 0.15s;
}

.radio-input::after {
  content: "";
  position: absolute;
  inset: 50%;
  transform: translate(-50%, -50%) scale(0);
  width: 0.5rem;
  height: 0.5rem;
  border-radius: 50%;
  background: var(--accent);
  transition: transform 0.15s ease;
}

.radio-input:checked {
  border-color: var(--accent);
  background: color-mix(in srgb, var(--accent) 12%, var(--bg));
}
.radio-input:checked::after { transform: translate(-50%, -50%) scale(1); }

/* Highlight the whole row when checked */
.radio-input:checked + .radio-text {
  color: var(--text);
}
.radio-label:has(.radio-input:checked) {
  border-color: var(--accent);
  background: color-mix(in srgb, var(--accent) 10%, var(--card));
}

/* Focus ring – meets 3:1 against dark background */
.radio-input:focus-visible {
  outline: 2px solid var(--border-focus);
  outline-offset: 2px;
}

/* ── Error message ────────────────────────────────────────────── */
.field-error {
  display: none;
  align-items: center;
  gap: 0.4rem;
  margin-top: 0.75rem;
  padding: 0.625rem 0.875rem;
  background: var(--error-bg);
  border: 1px solid color-mix(in srgb, var(--error) 40%, transparent);
  border-radius: var(--radius);
  font-size: 0.85rem;
  color: var(--error);
}
.field-error[aria-hidden="false"],
.field-error:not([aria-hidden]) { display: flex; }
.field-error svg { flex-shrink: 0; }

/* ── Status banner ────────────────────────────────────────────── */
.status-banner {
  margin-top: 1.25rem;
  padding: 0.75rem 1rem;
  border-radius: var(--radius);
  font-size: 0.9rem;
  font-weight: 500;
}
.status-banner[data-type="success"] {
  background: var(--success-bg);
  border: 1px solid color-mix(in srgb, var(--success) 40%, transparent);
  color: var(--success);
}
.status-banner[data-type="error"] {
  background: var(--error-bg);
  border: 1px solid color-mix(in srgb, var(--error) 40%, transparent);
  color: var(--error);
}
.status-banner:empty { display: none; }

/* ── Submit button ────────────────────────────────────────────── */
.form-actions { margin-top: 1.75rem; }

.btn-submit {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  width: 100%;
  padding: 0.75rem 1.5rem;
  background: var(--accent);
  color: #0d1117;
  font-size: 0.9375rem;
  font-weight: 700;
  border: none;
  border-radius: var(--radius);
  cursor: pointer;
  transition: background 0.15s, transform 0.1s;
  letter-spacing: 0.01em;
}
.btn-submit:hover  { background: var(--accent-hover); }
.btn-submit:active { background: var(--accent-active); transform: scale(0.98); }
.btn-submit:focus-visible {
  outline: 2px solid var(--border-focus);
  outline-offset: 2px;
}

/* ── Forced-colors (Windows High Contrast) ────────────────────── */
@media (forced-colors: active) {
  .radio-input { forced-color-adjust: auto; }
  .radio-label { border-color: ButtonText; }
  .radio-label:hover,
  .radio-label:has(.radio-input:checked) { border-color: Highlight; }
  .btn-submit { forced-color-adjust: auto; }
}

/* ── Reduced motion ───────────────────────────────────────────── */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { transition: none !important; }
}

/* ── Reflow / 320 px ──────────────────────────────────────────── */
@media (max-width: 360px) {
  .card { padding: 1.25rem; }
  .card__title { font-size: 1.25rem; }
}
