   --shadow:       0 4px 24px rgba(0,0,0,.5);
 }

 html { font-size: 16px; }

 body {
   font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto,
                "Helvetica Neue", Arial, sans-serif;
   background: var(--bg);
   color: var(--text);
   min-height: 100vh;
   display: flex;
