   const options = [
     { value: "email", label: "Email" },
     { value: "sms",   label: "SMS" },
     { value: "push",  label: "Push Notifications" },
   ];

   return html`
     <form id="notification-form" novalidate>
       <p class="required-note">
         Fields marked <span class="star" aria-hidden="true">*</span>
         <span class="sr-only">with an asterisk</span> are required.
       </p>

       ${RadioButtonGroup({
         groupName: "notification-preference",
         legend: "How do you prefer to receive notifications?",
         required: true,
         options,
         errorId: "notif-error",
