// ── Utility ───────────────────────────────────────────────────────────────
function html(strings, ...values) {
  return strings.reduce((acc, str, i) =>
    acc + str + (values[i] != null ? values[i] : ""), "");
}

// ── Components ────────────────────────────────────────────────────────────

function RadioOption({ id, name, value, label }) {
  return html`
    <label class="radio-label" for="${id}">
      <input
        class="radio-input"
        type="radio"
        id="${id}"
        name="${name}"
        value="${value}"
        required
      >
      <span class="radio-text">${label}</span>
    </label>
  `;
}

function RadioButtonGroup({ groupName, legend, required, options, errorId }) {
  const requiredMarker = required
    ? html`<span class="star" aria-hidden="true"> *</span>`
    : "";

  const optionsHtml = options
    .map((opt) =>
      RadioOption({
        id: `${groupName}-${opt.value}`,
        name: groupName,
        value: opt.value,
        label: opt.label,
      })
    )
    .join("");

  return html`
    <fieldset class="form-field" aria-describedby="${errorId}">
      <legend>${legend}${requiredMarker}</legend>
      <div class="radio-options" role="presentation">
        ${optionsHtml}
      </div>
      <div
        id="${errorId}"
        class="field-error"
        role="alert"
        aria-hidden="true"
      >
        <svg width="16" height="16" viewBox="0 0 16 16" aria-hidden="true" focusable="false" fill="currentColor">
