        id="form-status"
        class="status-banner"
        role="status"
        aria-live="polite"
        aria-atomic="true"
      ></div>
    </form>
  `;
}

function App() {
  return html`
    <div class="card" role="region" aria-labelledby="page-title">
      <p class="card__eyebrow" aria-hidden="true">Settings</p>
      <h1 class="card__title" id="page-title">Notification Preferences</h1>
      <p class="card__subtitle">
        Choose how you'd like us to reach you for updates and alerts.
      </p>
      ${NotificationForm()}
    </div>
  `;
}

// ── Mount ─────────────────────────────────────────────────────────────────
document.getElementById("app").innerHTML = App();

// ── Behaviour ─────────────────────────────────────────────────────────────
const form     = document.getElementById("notification-form");
const errorEl  = document.getElementById("notif-error");
const statusEl = document.getElementById("form-status");

function showError() {
  errorEl.setAttribute("aria-hidden", "false");
  const first = form.querySelector('input[type="radio"]');
  if (first) first.focus();
}

