  e.preventDefault();
  statusEl.textContent = "";
  statusEl.removeAttribute("data-type");

  const selected = form.querySelector('input[name="notification-preference"]:checked');

  if (!selected) {
    showError();
    return;
  }

  clearError();

  const labelMap = { email: "Email", sms: "SMS", push: "Push Notifications" };
  showStatus(
    `\u2713 Preference saved: ${labelMap[selected.value] || selected.value}`,
    "success"
  );
});
