}

.card__subtitle {
  font-size: 0.9rem;
  color: var(--text-muted);
  margin-bottom: 1.75rem;
}

/* ── Required legend ──────────────────────────────────────────── */
.required-note {
  font-size: 0.8rem;
  color: var(--text-muted);
  margin-bottom: 1.25rem;
}
.required-note .star { color: var(--error); }

/* ── Form field ───────────────────────────────────────────────── */
.form-field {
  border: none;
  padding: 0;
  min-inline-size: 0;
}

.form-field legend {
  font-size: 0.9rem;
  font-weight: 600;
  color: var(--text);
  margin-bottom: 1rem;
  line-height: 1.4;
  float: left;
  width: 100%;
}
/* Clear float so options sit below the legend */
.form-field legend + * { clear: both; }

.form-field legend .star { color: var(--error); margin-left: 0.125rem; }

/* ── Radio options ────────────────────────────────────────────── */
.radio-options {
  display: flex;
  flex-direction: column;
  gap: 0.625rem;
}

.radio-label {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  padding: 0.75rem 1rem;
  background: var(--card);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  cursor: pointer;
  font-size: 0.9375rem;
  color: var(--text-muted);
  transition: border-color 0.15s, color 0.15s, background 0.15s;
  user-select: none;
}

.radio-label:hover {
  border-color: var(--accent);
  color: var(--text);
  background: color-mix(in srgb, var(--accent) 8%, var(--card));
}

